202	func (s *Store) deleteAttachmentStorageImpl(ctx context.Context, attachment *Attachment, instanceStorageSetting *storepb.InstanceStorageSetting) error {
203		if attachment == nil {
204			return nil
205		}
206		if shouldFailDeleteAttachmentStorage(ctx) {
207			return ErrDeleteAttachmentStorageFailpoint
208		}
209	
210		if attachment.StorageType == storepb.AttachmentStorageType_LOCAL {
211			if err := func() error {
212				p := filepath.FromSlash(attachment.Reference)
213				if !filepath.IsAbs(p) {
214					p = filepath.Join(s.profile.Data, p)
215				}
216				err := os.Remove(p)
217				if err != nil && !os.IsNotExist(err) {
218					return errors.Wrap(err, "failed to delete local file")
219				}
220				return nil
221			}(); err != nil {
222				return err
223			}
224		} else if attachment.StorageType == storepb.AttachmentStorageType_S3 {
225			if err := func() error {
226				s3ObjectPayload := attachment.Payload.GetS3Object()
227				if s3ObjectPayload == nil {
228					return errors.Errorf("No s3 object found")
229				}
230				s3Config := s3ObjectPayload.S3Config
231				if s3Config == nil {
232					if instanceStorageSetting == nil {
233						var err error
234						instanceStorageSetting, err = s.GetInstanceStorageSetting(ctx)
235						if err != nil {
236							return errors.Wrap(err, "failed to get instance storage setting")
237						}
238					}
239					if instanceStorageSetting.S3Config == nil {
240						return errors.Errorf("S3 config is not found")
241					}
242					s3Config = instanceStorageSetting.S3Config
243				}
244	
245				s3Client, err := s3.NewClient(ctx, s3Config)
246				if err != nil {
247					return errors.Wrap(err, "Failed to create s3 client")
248				}
249				if err := s3Client.DeleteObject(ctx, s3ObjectPayload.Key); err != nil {
250					return errors.Wrap(err, "Failed to delete s3 object")
251				}
252				return nil
253			}(); err != nil {
254				return err
255			}
256		}
257	
258		s.deleteAttachmentDerivedCaches(attachment)
259		return nil
260	}
261	
262	func (s *Store) getAttachmentStorageCleanupInstanceSetting(ctx context.Context, attachments []*Attachment) (*storepb.InstanceStorageSetting, error) {
263		for _, attachment := range attachments {
264			if AttachmentNeedsInstanceStorageSetting(attachment) {
265				instanceStorageSetting, err := s.GetInstanceStorageSetting(ctx)
266				if err != nil {
267					return nil, errors.Wrap(err, "failed to get instance storage setting")
268				}
269				return instanceStorageSetting, nil
270			}
271		}
272		return nil, nil
273	}
274	
275	// AttachmentNeedsInstanceStorageSetting reports whether S3 cleanup needs the instance fallback storage setting.
276	func AttachmentNeedsInstanceStorageSetting(attachment *Attachment) bool {
277		if attachment == nil || attachment.StorageType != storepb.AttachmentStorageType_S3 {
278			return false
279		}
280		s3ObjectPayload := attachment.Payload.GetS3Object()
281		return s3ObjectPayload != nil && s3ObjectPayload.S3Config == nil
282	}
283	
284	func (s *Store) deleteAttachmentDerivedCaches(attachment *Attachment) {
285		for _, cachePath := range []string{
286			filepath.Join(s.profile.Data, thumbnailCacheFolder, attachment.UID+".jpeg"),
287			filepath.Join(s.profile.Data, motionCacheFolder, attachment.UID+".mp4"),
288		} {
289			if err := os.Remove(cachePath); err != nil && !os.IsNotExist(err) {
290				slog.Warn("Failed to delete derived attachment cache", slog.String("path", cachePath), slog.Any("err", err))
291			}
292		}
293	}
294	
295	func shouldFailDeleteAttachmentStorage(ctx context.Context) bool {
296		failpoint, ok := ctx.Value(deleteAttachmentStorageFailpointKey{}).(bool)
297		return ok && failpoint
298	}
